    return fbb.DataBuffer.ToSizedArray();
  }
}


static public class FMBVerify
{
  static public bool Verify(Google.FlatBuffers.Verifier verifier, uint tablePos)
  {
    return verifier.VerifyTableStart(tablePos)
      && verifier.VerifyField(tablePos, 4 /*SELF_OFFSET*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyField(tablePos, 6 /*PREVIOUS*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyField(tablePos, 8 /*FEED_ID*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 10 /*COMMITTED_AT*/, 8 /*long*/, 8, false)
      && verifier.VerifyField(tablePos, 12 /*TYPE_SEQ_HIGH*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyVectorOfData(tablePos, 14 /*ROWS*/, 40 /*FMBRow*/, false)
      && verifier.VerifyVectorOfData(tablePos, 16 /*DIGESTS*/, 1 /*byte*/, false)
      && verifier.VerifyVectorOfData(tablePos, 18 /*GROUPS*/, 24 /*FMBGroup*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 20 /*DICTIONARY*/, FMBEntryVerify.Verify, false)
      && verifier.VerifyVectorOfData(tablePos, 22 /*REMOVALS*/, 16 /*FMBRemove*/, false)
      && verifier.VerifyVectorOfData(tablePos, 24 /*URLS*/, 16 /*FMBUrl*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 26 /*SIGNATURES*/, FMBSignatureVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 28 /*SEALED*/, FMBSealedVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 30 /*IDENTITIES*/, FMBIdentityVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 32 /*LARGE*/, FMBLargeVerify.Verify, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
